SINA_SMART["biophys1-radioprotection"] = {"lecture":"biophys1-radioprotection","title":"Radiation protection and safety in the medical sector","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biophys1-radioprotection:e0","text":"RP: protect people and environment while allowing justified use.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e1","text":"ICRP 1928; UNSCEAR; IAEA; Morocco: CNRP, AMSSNuR.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e2","text":"Natural exposure largest: cosmic 0.2 mSv/yr (sea level), soil 0.3-0.5, K-40 0.25.","topic":"Sources of exposure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e3","text":"Medical ≈ 1 mSv/yr; artificial ≈ 0.1 mSv/yr.","topic":"Sources of exposure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e7","text":"Worker A 20 mSv/yr; B 6 mSv/yr; public 1 mSv/yr; pregnancy < 1 mSv abdomen.","topic":"Sources of exposure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e4","text":"External exposure: time, distance, shielding.","topic":"Modes of exposure","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e5","text":"Internal contamination: inhalation, ingestion, wounds; I-131 thyroid, Sr-90 bone.","topic":"Modes of exposure","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e6","text":"Principles: justification, optimisation (ALARA), limitation.","topic":"Principles, limits and monitoring","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e8","text":"Lens limit 150 mSv/yr (A); extremities 500 mSv/yr.","topic":"Principles, limits and monitoring","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-radioprotection:e9","text":"Controlled area > 3/10, supervised > 1/10 of limits; TLD/OSL, ring, electronic dosimeters.","topic":"Principles, limits and monitoring","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"e0pjwc":"a","1p79y97":"a","1uoob4o":"a","1ooqemv":"a","8s0gsp":"a","12iolny":"a","1xakqou":"a","1uyt2uk":"a","1uo7ijh":"a","17b2xte":"a","pihepn":"a","7xaqn8":"a","s1we8w":"a","124hdm5":"a","10k70n8":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biophys1-radioprotection:e0":{"s":0,"u":["RP: protect people and environment while allowing justified use.","Radiation protection is the set of technical, legal and administrative measures that protect people and the environment from the harmful effects of ionising radiation while allowing its controlled, justified use: a balance of risk and expected benefit ."],"dp":[]},"biophys1-radioprotection:e1":{"s":0,"u":["ICRP 1928; UNSCEAR; IAEA; Morocco: CNRP, AMSSNuR.","Organisation: international ICRP , UNSCEAR , IAEA ; European Euratom ; in Morocco the CNRP (National Center for Radiation Protection) and AMSSNuR (Moroccan Agency for Nuclear and Radiological Safety and Security).","History: 1902 first radiation-induced cancers in physicians and physicists; 1921 committee for protection against X-rays; 1928 creation of the ICRP ."],"dp":[]},"biophys1-radioprotection:e2":{"s":1,"u":["Natural exposure largest: cosmic 0.2 mSv/yr (sea level), soil 0.3-0.5, K-40 0.25.","Natural (largest source): cosmic rays ( 0.2 mSv/year at sea level , 0.4 at 1,500 m, more when flying), soil radionuclides (U-238, Th-232: 0.3-0.5 mSv/year), and body radionuclides, mainly potassium-40 (~0.25 mSv/year)."],"dp":[]},"biophys1-radioprotection:e3":{"s":1,"u":["Medical ≈ 1 mSv/yr; artificial ≈ 0.1 mSv/yr.","Artificial (industry, nuclear test fallout): ~0.1 mSv/year.","Medical : ~ 1 mSv/year on average, where the patient benefits directly (X-rays, CT, radiotherapy); effective dose is the key risk quantity."],"dp":[]},"biophys1-radioprotection:e7":{"s":1,"u":["Worker A 20 mSv/yr; B 6 mSv/yr; public 1 mSv/yr; pregnancy < 1 mSv abdomen.","Natural (largest source): cosmic rays ( 0.2 mSv/year at sea level , 0.4 at 1,500 m, more when flying), soil radionuclides (U-238, Th-232: 0.3-0.5 mSv/year), and body radionuclides, mainly potassium-40 (~0.25 mSv/year).","Artificial (industry, nuclear test fallout): ~0.1 mSv/year."],"dp":[]},"biophys1-radioprotection:e4":{"s":2,"u":["External exposure: time, distance, shielding.","External exposure : the source is outside the body, no intake; reduced by the three rules time, distance, shielding (lead syringe shields, shielded hoods and screens, gamma cameras run from a separate room, lead aprons for accompanying parents)."],"dp":[{"h":"Why distance is such a powerful protection","t":"Radiation from a small source spreads out in all directions, so its intensity falls with the square of the distance. Doubling the distance cuts the dose rate to a quarter; stepping back a metre or two from a patient injected with a tracer reduces exposure far more than most shields, at no cost. Source: the lecture's three principles of external exposure reduction."}]},"biophys1-radioprotection:e5":{"s":2,"u":["Internal contamination: inhalation, ingestion, wounds; I-131 thyroid, Sr-90 bone.","Internal contamination : intake by inhalation, ingestion or wounds ; behaviour depends on chemical form: I-131 concentrates in the thyroid , Sr-90 in bone , others are excreted; risks include local organ irradiation and long-term cancer."],"dp":[]},"biophys1-radioprotection:e6":{"s":3,"u":["Principles: justification, optimisation (ALARA), limitation.","Three principles: justification (net benefit; avoid useless exposure; a useful exam's result, positive or negative, changes management; the prescribing physician is responsible, the radiologist or nuclear physician decides), optimisation ( ALARA : as low as reasonably achievable) and limitation (dose limits)."],"dp":[{"h":"Why medical exposure has no dose limit","t":"Dose limits protect workers and the public, who gain nothing from their exposure. A patient receiving a CT scan or radiotherapy benefits directly, so the dose is governed by justification (is the exam useful?) and optimisation (lowest dose for a diagnostic image), not by a fixed limit that could prevent necessary care. Source: the lecture's medical irradiation and principles slides."}]},"biophys1-radioprotection:e8":{"s":3,"u":["Lens limit 150 mSv/yr (A); extremities 500 mSv/yr.","Limits : category A workers (may exceed 3/10 of limits): 20 mSv/year whole body, 500 mSv/year skin/extremities, 150 mSv/year lens; category B : 6 mSv/year, 150 skin, 45 lens; public : 1 mSv/year ; pregnant worker: to the abdomen."],"dp":[]},"biophys1-radioprotection:e9":{"s":3,"u":["Controlled area > 3/10, supervised > 1/10 of limits; TLD/OSL, ring, electronic dosimeters.","Zoning : controlled area (possible dose > 3/10 of a limit) and supervised area (> 1/10), marked and access-restricted.","Controls : sources and facilities (containers, shielding, ventilation, interlocks, signage), environment (fixed and portable detectors, contamination and air monitoring), and workers: passive regulatory dosimeter (TLD or OSL; records doses), ring dosimeter for syringe handling, active operational electronic dosimeter for real-time reading."],"dp":[]}},"meta":{"e0pjwc":{"a":"recall","vg":"biophys1-radioprotection:e1/recall/1"},"1p79y97":{"a":"recall","vg":"biophys1-radioprotection:e1/recall/2"},"1uoob4o":{"a":"recall","vg":"biophys1-radioprotection:e2/recall/1"},"1ooqemv":{"a":"recall","vg":"biophys1-radioprotection:e2/recall/2"},"8s0gsp":{"a":"recall","vg":"biophys1-radioprotection:e2/recall/3"},"12iolny":{"a":"recall","vg":"biophys1-radioprotection:e3/recall/1"},"1xakqou":{"a":"recall","vg":"biophys1-radioprotection:e4/recall/1"},"1uyt2uk":{"a":"recall","vg":"biophys1-radioprotection:e5/recall/1"},"1uo7ijh":{"a":"recall","vg":"biophys1-radioprotection:e5/recall/2"},"17b2xte":{"a":"recall","vg":"biophys1-radioprotection:e6/recall/1"},"pihepn":{"a":"recall","vg":"biophys1-radioprotection:e8/recall/1"},"7xaqn8":{"a":"recall","vg":"biophys1-radioprotection:e8/recall/1"},"s1we8w":{"a":"recall","vg":"biophys1-radioprotection:e8/recall/1"},"124hdm5":{"a":"recall","vg":"biophys1-radioprotection:e9/recall/1"},"10k70n8":{"a":"recall","vg":"biophys1-radioprotection:e9/recall/2"}},"explRev":"1a68e507798f"};
